import { activeCashFlows, activeSnapshots, migratePortfolio } from './portfolio-ledger';
import { ASSET_CODES, type AssetCode, type AssetRecordQuality, type CashFlowEvent, type LocalPosition, type MarketSeriesBundle, type PerformancePoint, type PerformanceSummary } from './types';

const QUALITY_LABEL: Record<AssetRecordQuality, string> = {
  CONFIRMED: '已确认资产记录',
  ESTIMATED: '估算，需核对',
  UNAVAILABLE: '暂无法计算收益',
};

function rawPriceMap(market: MarketSeriesBundle): Map<string, Partial<Record<AssetCode, number>>> {
  const result = new Map<string, Partial<Record<AssetCode, number>>>();
  ASSET_CODES.forEach((code) => {
    market.assets[code]?.bars.forEach((bar) => {
      if (bar.rawClose == null || !Number.isFinite(bar.rawClose) || bar.rawClose <= 0) return;
      const row = result.get(bar.date) ?? {};
      row[code] = bar.rawClose;
      result.set(bar.date, row);
    });
  });
  return result;
}

export function cashFlowEffectiveDate(flow: CashFlowEvent, valuationDates: string[]): string | null {
  if (flow.valuationEffectiveDate && valuationDates.includes(flow.valuationEffectiveDate)) return flow.valuationEffectiveDate;
  return valuationDates.find((date) => date >= flow.date) ?? null;
}

function valuePosition(position: LocalPosition | undefined, rawPrice: number | undefined, originRawPrice: number | undefined, snapshotValue: number): { value: number; estimated: boolean; valid: boolean } {
  if (!position) return { value: 0, estimated: false, valid: true };
  if (position.inputMode === 'QUANTITY') {
    if (position.quantity == null || position.quantity < 0 || rawPrice == null) return { value: 0, estimated: false, valid: false };
    return { value: position.quantity * rawPrice, estimated: false, valid: true };
  }
  if (position.confirmedMarketValue == null || position.confirmedMarketValue < 0) return { value: 0, estimated: true, valid: false };
  if (snapshotValue <= 0) return { value: 0, estimated: false, valid: true };
  if (rawPrice == null || originRawPrice == null || originRawPrice <= 0) return { value: 0, estimated: true, valid: false };
  return { value: position.confirmedMarketValue / originRawPrice * rawPrice, estimated: true, valid: true };
}

export function calculatePerformance(rawPortfolio: Parameters<typeof migratePortfolio>[0], market?: MarketSeriesBundle): PerformanceSummary {
  const portfolio = migratePortfolio(rawPortfolio);
  const snapshots = activeSnapshots(portfolio);
  const cashFlows = activeCashFlows(portfolio);
  const baselineDate = portfolio.baseline?.date ?? null;
  const issues: string[] = [];
  const invested = Object.values(portfolio.values).reduce((sum, value) => sum + Math.max(0, value ?? 0), 0);
  const currentTotal = invested + Math.max(0, portfolio.cash);
  const positions = Object.values(portfolio.positionsByCode ?? {}).filter((item): item is LocalPosition => Boolean(item));
  const activePositions = positions.filter((item) => (item.inputMode === 'QUANTITY' ? item.quantity ?? 0 : item.confirmedMarketValue ?? 0) > 0);
  const confirmedQuantity = activePositions.filter((item) => item.inputMode === 'QUANTITY' && item.estimationStatus === 'CONFIRMED').length;
  const coverage = activePositions.length ? confirmedQuantity / activePositions.length : 0;
  if (!baselineDate || snapshots.length < 1 || currentTotal <= 0) {
    return {
      quality: 'UNAVAILABLE', qualityLabel: QUALITY_LABEL.UNAVAILABLE, baselineDate,
      latestDate: snapshots.at(-1)?.asOf ?? null, totalAssets: currentTotal > 0 ? currentTotal : null,
      profit: null, cumulativeReturn: null, currentDrawdown: null, maxDrawdown: null,
      underwaterTradingDays: null, netCashFlow: 0, points: [],
      issues: ['确认当前持仓后建立首份资产基线；系统不会反推过去收益。'], confirmedQuantityCoverage: coverage,
    };
  }
  if (!market) {
    return {
      quality: 'UNAVAILABLE', qualityLabel: QUALITY_LABEL.UNAVAILABLE, baselineDate,
      latestDate: snapshots.at(-1)?.asOf ?? null, totalAssets: snapshots.at(-1)?.totalAssets ?? currentTotal,
      profit: null, cumulativeReturn: null, currentDrawdown: null, maxDrawdown: null,
      underwaterTradingDays: null, netCashFlow: 0, points: [],
      issues: ['未加载未复权估值序列。'], confirmedQuantityCoverage: coverage,
    };
  }
  const prices = rawPriceMap(market);
  const dates = [...prices.keys()].filter((date) => date >= baselineDate).sort();
  const flowByDate = new Map<string, number>();
  cashFlows.forEach((flow) => {
    const effectiveDate = cashFlowEffectiveDate(flow, dates);
    if (!effectiveDate) {
      issues.push(`${flow.date}现金流等待下一有效估值日`);
      return;
    }
    const signed = flow.type === 'CONTRIBUTION' ? flow.amount : -flow.amount;
    flowByDate.set(effectiveDate, (flowByDate.get(effectiveDate) ?? 0) + signed);
  });
  const activeSnapshotByDate = new Map(snapshots.map((item) => [item.asOf, item]));
  const points: PerformancePoint[] = [];
  let snapshotIndex = 0;
  let source = snapshots[0]!;
  let nav = 1;
  let highNav = 1;
  let underwaterTradingDays = 0;
  let previousValue: number | null = null;
  let overallQuality: AssetRecordQuality = source.accuracy;
  for (const date of dates) {
    while (snapshotIndex + 1 < snapshots.length && snapshots[snapshotIndex + 1]!.asOf <= date) {
      snapshotIndex += 1;
      source = snapshots[snapshotIndex]!;
    }
    if (date < source.asOf) continue;
    const exact = activeSnapshotByDate.get(date);
    const raw = prices.get(date) ?? {};
    const originRaw = prices.get(source.priceDate) ?? prices.get(source.asOf) ?? {};
    let totalAssets = source.cash;
    let estimated = source.accuracy === 'ESTIMATED';
    let valid = true;
    ASSET_CODES.forEach((code) => {
      const result = valuePosition(source.positionsByCode[code], raw[code], originRaw[code], source.values[code] ?? 0);
      totalAssets += result.value;
      estimated ||= result.estimated;
      valid &&= result.valid;
    });
    if (exact) totalAssets = exact.totalAssets;
    if (!valid || totalAssets <= 0) { issues.push(`${date}缺少可靠估值`); continue; }
    const cashFlow = flowByDate.get(date) ?? 0;
    const dailyReturn = previousValue == null ? null : (totalAssets - cashFlow) / previousValue - 1;
    if (dailyReturn != null && Number.isFinite(dailyReturn)) nav *= 1 + dailyReturn;
    highNav = Math.max(highNav, nav);
    const drawdown = highNav > 0 ? nav / highNav - 1 : 0;
    if (drawdown < -1e-10) underwaterTradingDays += 1;
    const pointQuality: AssetRecordQuality = estimated ? 'ESTIMATED' : 'CONFIRMED';
    if (pointQuality === 'ESTIMATED') overallQuality = 'ESTIMATED';
    points.push({ date, totalAssets, nav, cashFlow, dailyReturn, drawdown, quality: pointQuality });
    previousValue = totalAssets;
  }
  if (issues.length) overallQuality = 'ESTIMATED';
  if (points.length < 2) overallQuality = 'UNAVAILABLE';
  const first = points[0];
  const last = points.at(-1);
  const netCashFlow = cashFlows.filter((flow) => !baselineDate || flow.date >= baselineDate)
    .reduce((sum, flow) => sum + (flow.type === 'CONTRIBUTION' ? flow.amount : -flow.amount), 0);
  return {
    quality: overallQuality,
    qualityLabel: QUALITY_LABEL[overallQuality],
    baselineDate,
    latestDate: last?.date ?? snapshots.at(-1)?.asOf ?? null,
    totalAssets: last?.totalAssets ?? snapshots.at(-1)?.totalAssets ?? currentTotal,
    profit: first && last && points.length >= 2 ? last.totalAssets - first.totalAssets - netCashFlow : null,
    cumulativeReturn: first && last && points.length >= 2 ? last.nav / first.nav - 1 : null,
    currentDrawdown: first && last && points.length >= 2 ? last.drawdown : null,
    maxDrawdown: first && last && points.length >= 2 ? Math.min(...points.map((point) => point.drawdown)) : null,
    underwaterTradingDays: first && last && points.length >= 2 ? underwaterTradingDays : null,
    netCashFlow,
    points,
    issues: [...new Set(issues)],
    confirmedQuantityCoverage: coverage,
  };
}
