export function percent(value: number | null | undefined, digits = 1): string {
  return value == null || !Number.isFinite(value) ? '—' : new Intl.NumberFormat('zh-CN', {
    style: 'percent', maximumFractionDigits: digits, minimumFractionDigits: digits,
  }).format(value);
}

export function money(value: number | null | undefined): string {
  return value == null || !Number.isFinite(value) ? '—' : new Intl.NumberFormat('zh-CN', {
    style: 'currency', currency: 'CNY', maximumFractionDigits: 0,
  }).format(value);
}

export function number(value: number | null | undefined, digits = 2): string {
  return value == null || !Number.isFinite(value) ? '—' : value.toFixed(digits);
}

export function date(value: string, includeTime = false): string {
  const parsed = new Date(value);
  if (Number.isNaN(parsed.getTime())) return value;
  return new Intl.DateTimeFormat('zh-CN', includeTime
    ? { month: '2-digit', day: '2-digit', hour: '2-digit', minute: '2-digit', hour12: false }
    : { year: 'numeric', month: '2-digit', day: '2-digit' }).format(parsed);
}

export function escapeHtml(value: unknown): string {
  return String(value ?? '').replace(/[&<>"']/g, (character) => ({
    '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#039;',
  })[character] ?? character);
}

export function instrumentLabel(code: string, name?: string | null): string {
  const normalizedName = String(name ?? '').trim();
  return normalizedName ? `${code} ${normalizedName}` : code;
}
